class TreasuryComposer:
    """Composer for creating transaction groups for Treasury contract calls"""

    def __init__(self, client: "TreasuryClient"):
        self.client = client
        self._composer = client.algorand.new_group()
        self._result_mappers: list[typing.Callable[[algokit_utils.ABIReturn | None], object] | None] = []

    def configure(
        self,
        args: tuple[algokit_utils.AppMethodCallTransactionArgument, list[tuple[str, int, int]]] | ConfigureArgs,
        params: algokit_utils.CommonAppCallParams | None = None
    ) -> "TreasuryComposer":
        self._composer.add_app_call_method_call(
            self.client.params.configure(
                args=args,
                params=params,
            )
        )
        self._result_mappers.append(
            lambda v: self.client.decode_return_value(
                "configure(pay,(address,uint64,uint64)[])uint64", v
            )
        )
        return self

